'use strict';
// Checked-in browser bundle. Installing/running the plugin needs no build or npm install.
const fs=require('node:fs'),path=require('node:path');
const root=path.resolve(__dirname,'..');
const inputs=['server/public/vendor/purify.min.js','server/public/vendor/showdown.min.js','server/renderer-source.js'];
const bundle='/* Silly Bookshop renderer bundle; licenses in vendor/. Generated by scripts/build-renderer.cjs. */\n'+inputs.map(file=>fs.readFileSync(path.join(root,file),'utf8').replace(/^\/\/# sourceMappingURL=.*$/gm,'')).join('\n;\n');
const output=path.join(root,'server/public/rich.js');
if(process.argv.includes('--check')){if(fs.readFileSync(output,'utf8')!==bundle){console.error('Renderer bundle is stale. Run node scripts/build-renderer.cjs');process.exitCode=1;}}
else{fs.writeFileSync(output,bundle);console.log('Bundled renderer: '+Buffer.byteLength(bundle)+' bytes');}
